	sections = {
		{
			title = "概述",
			text = [=[夺灵者哈卡是{link:trolls}巨魔{/link}的血神，一位有着可怕饥渴的洛阿。巨魔崇拜许多神灵，但没有一位像他这样令人畏惧。哪里尊崇哈卡，哪里就会流血。他在生者中的仆从是阿塔莱，一个曾为古拉巴什帝国效力的祭司教派。他的有翼之蛇仍出没于他曾受崇拜的地方，巨魔们说，荒野中的风蛇是他的亲族。]=],
		},
		{
			title = "意义",
			text = [=[哈卡几乎摧毁了南方的{link:trolls}巨魔{/link}帝国。在{link:great-sundering}大分裂{/link}之后，古拉巴什失去了大片土地，他们的祭司在困境中转向了黑暗的力量。阿塔莱在{link:zul-gurub}祖尔格拉布{/link}把哈卡召唤到了这个世界。他来了，并索要鲜血。他以召唤他的子民本身为食。最终，古拉巴什各部族起来反抗这位神灵和他的祭司。他们推翻了他，把阿塔莱驱逐出境。帝国再也没有恢复元气。它的部族彼此反目，它的城市被留给了丛林。

阿塔莱并没有失去信仰。他们在{link:swamp-of-sorrows}悲伤沼泽{/link}为他建起了一座神庙，在那里为他的归来做准备。{red:ysera}伊瑟拉{/red}把那座神庙沉入沼泽之下，从那以后她的巨龙一直监视着它。但这还不够。幸存的阿塔莱仍在神庙深处努力，要把他从虚空中召回。

巨魔们讲述着关于他的两个故事。在一个故事里，他的到来将为所有巨魔带来欢乐和荣耀。在另一个故事里，他的归来将标志着万物的终结。那些见过他的祭司所作所为的人，相信的是第二个。

阿塔莱并不是他唯一的仆从。在{link:the-hinterlands}辛特兰{/link}，{red:vilebranch-trolls}邪枝巨魔{/red}在他们的都城{link:jintha-alor}辛萨罗{/link}把俘虏献给他，那里盛放污染之血的容器驱使他们陷入疯狂。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:zul-gurub}祖尔格拉布{/link}被阿塔莱召唤到这个世界，以他自己的崇拜者为食。
• 他被古拉巴什各部族推翻，他们把他的祭司驱逐出境。
• 他的灵魂被禁锢在堕落之神的圣所中，处于永恒之火之下。]=],
		},
		{
			title = "未载之事",
			text = [=[这个时代的史书没有记载哈卡最初何时来到{link:trolls}巨魔{/link}之中，也没有记载古拉巴什推翻他的那一年。]=],
		},
	},
	chapters = {
		{
			title = "淹没的圣殿",
			hint = "帮助一位老探险家找到一座失落的神庙。",
			text = [=[对{link:explorers-league}探险者协会{/link}的学者们来说，{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}是一个传说：夺灵者的一座神圣圣殿，由一个凶残的部族看守，据说根本无法进入。{link:brohann-caskbelly}布罗哈恩·铁桶{/link}把他的晚年都花在了寻找它上面。他终于找到了它，它沉在{link:pool-of-tears}泪水之池{/link}的水下，他还得知，他的搜寻者带给他的每一块石板上都写着它的神的名字。]=],
		},
		{
			title = "摩沙鲁的预言",
			hint = "听听塔纳利斯的一位巨魔学者对这位死去的神了解到了什么。",
			text = [=[在{link:tanaris}塔纳利斯{/link}，{link:trolls}巨魔{/link}{link:yeh-kinya}叶基亚{/link}谈到了巨魔古老的预言，说那位死去的神终有一天会回到大地上。他并不相信这个神话。但他确实相信哈卡的精华蕴含着巨大的力量，必须让它远离那些会滥用它的人。从很久以前被带到{red:zul-farrak}祖尔法拉克{/red}的{link:jammal-an-the-prophet}预言者{/link}摩沙鲁的石板中，他得知了一枚古老的蛋如何能够容纳那种精华。]=],
		},
		{
			title = "蛋的躁动",
			hint = "把蛋带进堕落之神的圣所。",
			text = [=[哈卡之卵被带进了淹没的神庙，在那里，它的力量惊动了这位神灵。他的化身降临到这个世界，随即被摧毁，他的精华被封存在蛋中。当它被带回{link:tanaris}塔纳利斯{/link}时，它开始躁动，显出了生命的迹象。{link:yeh-kinya}叶基亚{/link}感到不安。他从前不相信那些神话，如今他害怕哈卡若是重生会做出什么。他发誓要保护好这枚蛋。]=],
		},
	},
	mentions = {
		{ text = "{link:pool-of-tears}泪水之池{/link}" },
		{ text = "{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}" },
		{ text = "{link:jammal-an-the-prophet}预言者迦玛兰{/link}" },
		{ text = "摩沙鲁的预言" },
		{ text = "远古之卵" },
	},
	bonds = {
		{ id = "jammal-an-the-prophet", name = "预言者迦玛兰", note = "他的预言者" },
		{ id = "avatar-of-hakkar", name = "哈卡的化身", note = "他在世间的形态" },
		{ id = "shade-of-eranikus", name = "伊兰尼库斯的阴影", note = "他的看守者" },
	},
})

