	sections = {
		{
			title = "概述",
			text = [=[哈卡的化身是夺灵者进入这个世界的形态。在淹没的神庙深处的堕落之神的圣所里，永恒之火禁锢着{link:hakkar}哈卡{/link}的灵魂。神的守血者照管着这些火焰。如果用哈卡自己的仆从的血浇灭火焰，化身就会降临：一条巨大的有翼之蛇，燃烧着神的力量。它并不是完整的哈卡。它是他灵魂的容器，神灵通过它再一次伸手触及{link:azeroth}艾泽拉斯{/link}。]=],
		},
		{
			title = "意义",
			text = [=[化身是阿塔莱的希望，也是其他所有人的恐惧。{link:jammal-an-the-prophet}预言者迦玛兰{/link}毕生都在为这次降临做准备，因为他相信，这位神灵一旦归来，就会赐予他的子民永恒的生命。神庙的绿龙正是被派来防范这件事的。当圣所躁动时，它们的镇压者便冲进来阻止召唤，高喊着绝不能让{link:hakkar}哈卡{/link}归来。化身也可以被用来对付它的主人。根据{link:trolls}巨魔{/link}的一个古老预言，一枚远古之卵可以容纳神的精华，而击败化身是填满它的唯一方法。]=],
		},
		{ title = "事迹", text = [=[• 当永恒之火被浇灭时，它在圣所中升起。
• 它由神的守血者和阴影侍奉。
• 当它倒下时，神的精华可以被捕获。]=] },
		{ title = "未载之事", text = "这个时代的史书没有记载，自神庙沉没以来，阿塔莱是否曾以他们自己的仪式召唤出过化身。" },
	},
	chapters = {
		{
			title = "永恒之火",
			hint = "从塔纳利斯的巨魔学者那里学会如何惊动那位死去的神。",
			text = [=[{link:yeh-kinya}叶基亚{/link}把{link:hakkar}哈卡{/link}之卵送进了淹没的神庙，送到堕落之神的圣所。当它的力量被唤起时，神灵作出了回应。他派他的爪牙去攻击携带蛋的人。他们从他的守血者那里取得了哈卡之血，用它浇灭了禁锢他灵魂的火焰。当最后一道火焰熄灭时，化身进入了这个世界。它倒下了，它的精华被封存在蛋中。]=],
		},
		{
			title = "哈卡的神物",
			hint = "听听部落在斯通纳德的使者对阿塔莱有何担忧。",
			text = [=[{link:stonard}斯通纳德{/link}的{link:fel-zerul}费泽鲁尔{/link}担心，阿塔莱那些附了魔的神物是让神灵归来的仪式的关键。那位流放者曾警告说，如果{link:jammal-an-the-prophet}迦玛兰{/link}找到了正确的附魔，世界将陷入巨大的危险。费泽鲁尔称这个预言是一个会提前招致末日的愚蠢骗局，他想在它成真之前夺取那些神物。]=],
		},
	},
	mentions = {
		{ text = "神灵{link:hakkar}哈卡{/link}" },
		{ text = "远古之卵" },
		{ text = "{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}" },
	},
	bonds = {
		{ id = "hakkar", name = "哈卡", note = "它所化身的神" },
		{ id = "jammal-an-the-prophet", name = "预言者迦玛兰", note = "为它的降临做准备" },
		{ id = "shade-of-eranikus", name = "伊兰尼库斯的阴影", note = "被派来阻止它的降临" },
	},
})

Translate("zhCN", "shade-of-eranikus", {
